import { describe, it, expect } from "vitest";
import { buildUsageSummary } from "../src/core/loop-run/usage.js";
import type { UsageLedgerEntry } from "../src/core/loop-run/state.js";

function entry(overrides: Partial<UsageLedgerEntry> = {}): UsageLedgerEntry {
  return {
    executionId: 1,
    phase: "implement",
    client: "opencode",
    outcome: "succeeded",
    inputTokens: null,
    outputTokens: null,
    cacheReadTokens: null,
    cacheWriteTokens: null,
    reasoningTokens: null,
    totalTokens: null,
    costUsd: null,
    ...overrides,
  };
}

describe("buildUsageSummary", () => {
  it("returns zeroed summary for empty ledger", () => {
    const summary = buildUsageSummary([]);
    expect(summary.run).toEqual({
      inputTokens: 0,
      outputTokens: 0,
      cacheReadTokens: 0,
      cacheWriteTokens: 0,
      reasoningTokens: 0,
      totalTokens: 0,
      costUsd: 0,
      hasUnknownTokens: false,
      hasUnknownCost: false,
    });
    expect(summary.byIssue).toEqual({});
    expect(Object.keys(summary.byPhase)).toEqual(["implement", "verify", "merger", "review", "live-steering"]);
  });

  it("sums known numeric values across entries", () => {
    const ledger: UsageLedgerEntry[] = [
      entry({ inputTokens: 100, outputTokens: 200, totalTokens: 300, costUsd: 0.01 }),
      entry({ executionId: 2, inputTokens: 50, outputTokens: 100, totalTokens: 150, costUsd: 0.005 }),
    ];
    const summary = buildUsageSummary(ledger);
    expect(summary.run.inputTokens).toBe(150);
    expect(summary.run.outputTokens).toBe(300);
    expect(summary.run.totalTokens).toBe(450);
    expect(summary.run.costUsd).toBeCloseTo(0.015);
  });

  it("does not set hasUnknownTokens when totalTokens is known even if component fields are null", () => {
    const ledger: UsageLedgerEntry[] = [
      entry({ inputTokens: 100, outputTokens: null, totalTokens: 100 }),
    ];
    const summary = buildUsageSummary(ledger);
    expect(summary.run.hasUnknownTokens).toBe(false);
    expect(summary.run.inputTokens).toBe(100);
  });

  it("sets hasUnknownTokens when totalTokens is null", () => {
    const ledger: UsageLedgerEntry[] = [
      entry({ inputTokens: 100, outputTokens: 200, totalTokens: null }),
    ];
    const summary = buildUsageSummary(ledger);
    expect(summary.run.hasUnknownTokens).toBe(true);
  });

  it("sets hasUnknownCost when costUsd is null", () => {
    const ledger: UsageLedgerEntry[] = [
      entry({ costUsd: null }),
    ];
    const summary = buildUsageSummary(ledger);
    expect(summary.run.hasUnknownCost).toBe(true);
    expect(summary.run.costUsd).toBe(0);
  });

  it("groups totals by issue", () => {
    const ledger: UsageLedgerEntry[] = [
      entry({ issueId: "42", inputTokens: 100 }),
      entry({ executionId: 2, issueId: "42", inputTokens: 50 }),
      entry({ executionId: 3, issueId: "99", inputTokens: 200 }),
    ];
    const summary = buildUsageSummary(ledger);
    expect(summary.byIssue["42"].inputTokens).toBe(150);
    expect(summary.byIssue["99"].inputTokens).toBe(200);
  });

  it("groups totals by phase", () => {
    const ledger: UsageLedgerEntry[] = [
      entry({ phase: "implement", inputTokens: 100 }),
      entry({ executionId: 2, phase: "verify", inputTokens: 200 }),
      entry({ executionId: 3, phase: "implement", inputTokens: 50 }),
    ];
    const summary = buildUsageSummary(ledger);
    expect(summary.byPhase.implement.inputTokens).toBe(150);
    expect(summary.byPhase.verify.inputTokens).toBe(200);
    expect(summary.byPhase.merger.inputTokens).toBe(0);
    expect(summary.byPhase.review.inputTokens).toBe(0);
  });

  it("excludes entries without issueId from byIssue", () => {
    const ledger: UsageLedgerEntry[] = [
      entry({ inputTokens: 100 }),
    ];
    const summary = buildUsageSummary(ledger);
    expect(summary.byIssue).toEqual({});
  });

  it("handles mixed known and null values correctly", () => {
    const ledger: UsageLedgerEntry[] = [
      entry({ inputTokens: 100, outputTokens: null, costUsd: 0.01 }),
      entry({ executionId: 2, inputTokens: null, outputTokens: 50, costUsd: null }),
    ];
    const summary = buildUsageSummary(ledger);
    expect(summary.run.inputTokens).toBe(100);
    expect(summary.run.outputTokens).toBe(50);
    expect(summary.run.costUsd).toBe(0.01);
    expect(summary.run.hasUnknownTokens).toBe(true);
    expect(summary.run.hasUnknownCost).toBe(true);
  });

  it("sums cache and reasoning tokens independently", () => {
    const ledger: UsageLedgerEntry[] = [
      entry({ cacheReadTokens: 10, cacheWriteTokens: 20, reasoningTokens: 30 }),
      entry({ executionId: 2, cacheReadTokens: 5, cacheWriteTokens: 10, reasoningTokens: 15 }),
    ];
    const summary = buildUsageSummary(ledger);
    expect(summary.run.cacheReadTokens).toBe(15);
    expect(summary.run.cacheWriteTokens).toBe(30);
    expect(summary.run.reasoningTokens).toBe(45);
  });

  it("includes live-steering in byPhase with zero totals even when no entries exist", () => {
    const summary = buildUsageSummary([]);
    expect(summary.byPhase["live-steering"]).toMatchObject({
      inputTokens: 0,
      outputTokens: 0,
      totalTokens: 0,
      costUsd: 0,
      hasUnknownTokens: false,
      hasUnknownCost: false,
    });
  });
});

  it("stores a dismissible finished overlay when the run ends", () => {
    let state = createInkRunViewState({ maxContext: null });

