    expect(formatDisplayCost(workerDuring)).toBe("$0.35");
    expect(workerDuring.latestInputTokens).toBe(50000);
    expect(workerDuring.latestContextTokens).toBe(52000);

    // Second streaming update replaces (cumulative, not additive)
    state = applyLoopRunEventToInkState(state, {
      kind: "streamingUsage",
