export function displayHasUnknownCost(worker: WorkerDashboardRow): boolean {
  if (worker.usage.hasUnknownCost) return true;
  return worker.streamingUsage !== null && worker.streamingUsage.costUsd === null;
}

export function formatDisplayCost(worker: WorkerDashboardRow): string {
  if (displayHasUnknownCost(worker)) return "unknown";
  const total = worker.usage.costUsd + (worker.streamingUsage?.costUsd ?? 0);
  return `$${total.toFixed(2)}`;
}

